const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const path = require('path');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server, path: '/ws/chat' });

// Session store (simplified)
const sessions = new Map();

// Middleware to parse cookies
app.use((req, res, next) => {
  const cookies = {};
  (req.headers.cookie || '').split(';').forEach(c => {
    const [k, v] = c.trim().split('=');
    if (k) cookies[k] = v;
  });
  req.cookies = cookies;
  next();
});

// User dashboard with WebSocket connection
app.get('/dashboard', (req, res) => {
  const sessionId = req.cookies.session_id;
  if (!sessionId || !sessions.has(sessionId)) {
    return res.redirect('/login');
  }
  const user = sessions.get(sessionId);
  // Render dashboard with user-controlled "theme" parameter
  const theme = req.query.theme || 'default';

  res.send(`<!DOCTYPE html>
<html>
<head><title>Dashboard - ${user.name}</title></head>
<body class="theme-${theme}">
  <h1>Welcome, ${user.name}</h1>
  <div id="messages"></div>
  <script>
    const ws = new WebSocket('wss://' + location.host + '/ws/chat');
    ws.onmessage = function(evt) {
      const msg = JSON.parse(evt.data);
      document.getElementById('messages').innerHTML += 
        '<div class="msg">' + msg.content + '</div>';
    };
    ws.onopen = function() {
      ws.send(JSON.stringify({type: 'auth', token: '${sessionId}'}));
    };
  </script>
  <img src="/static/logo.png" onerror="this.src='/static/fallback.png'">
</body>
</html>`);
});

// WebSocket authentication and message handling
wss.on('connection', (ws, req) => {
  let authenticated = false;
  let currentUser = null;

  ws.on('message', (data) => {
    try {
      const msg = JSON.parse(data);

      if (msg.type === 'auth') {
        // Authenticate via session token sent over WebSocket
        if (sessions.has(msg.token)) {
          authenticated = true;
          currentUser = sessions.get(msg.token);
          ws.send(JSON.stringify({ type: 'auth_ok', user: currentUser.name }));
        } else {
          ws.send(JSON.stringify({ type: 'auth_fail' }));
          ws.close();
        }
        return;
      }

      if (!authenticated) {
        ws.close();
        return;
      }

      if (msg.type === 'chat') {
        // Broadcast message to all authenticated clients
        // NOTE: No origin validation on WebSocket upgrade
        const payload = JSON.stringify({
          type: 'message',
          content: msg.content,
          from: currentUser.name,
          timestamp: Date.now()
        });
        wss.clients.forEach(client => {
          if (client.readyState === WebSocket.OPEN) {
            client.send(payload);
          }
        });
      }

      if (msg.type === 'admin_action' && currentUser.role === 'admin') {
        // Execute admin commands
        const result = executeAdminCommand(msg.command, msg.params);
        ws.send(JSON.stringify({ type: 'admin_result', result }));
      }
    } catch (e) {
      ws.send(JSON.stringify({ type: 'error', message: 'Invalid message format' }));
    }
  });
});

function executeAdminCommand(command, params) {
  const commands = {
    'list_users': () => Array.from(sessions.values()).map(u => u.name),
    'kick_user': (p) => { sessions.delete(p.sessionId); return 'kicked'; },
    'broadcast': (p) => { return `Broadcast: ${p.message}`; }
  };
  if (commands[command]) return commands[command](params);
  return 'unknown command';
}

// Login endpoint
app.post('/login', express.urlencoded({ extended: false }), (req, res) => {
  const { username, password } = req.body;
  // Simplified auth
  if (username && password === 'valid') {
    const sid = require('crypto').randomBytes(16).toString('hex');
    sessions.set(sid, { name: username, role: username === 'admin' ? 'admin' : 'user' });
    res.cookie('session_id', sid, { httpOnly: true, sameSite: 'Strict' });
    res.redirect('/dashboard');
  } else {
    res.status(401).send('Invalid credentials');
  }
});

server.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
});
